SELECT /* BFFACDD01MAPPER.selectFruitSource */ FRUIT_ID , FRUIT_NAME , FRUIT_COLOR , FRUIT_QTY FROM T_FRUIT_SOURCE WHERE 1=1
AND FRUIT_COLOR = #{fruitColor}
AND FRUIT_QTY >= #{fruitQty}

mapper.update:
UPDATE T_FRUIT_TARGET /*  BFFACDD01MAPPER.updateFruitStatus */
SET STATUS = #{item.status}
  , UPDATED_AT = SYSDATE
WHERE TARGET_ID = #{item.targetId}

mapper.insert:
		INSERT/* iBFFACDD01MAPPER.nsertFruitTarget */  INTO T_FRUIT_TARGET (
              TARGET_ID
            , TARGET_NAME
            , FRUIT_QTY
            , PROCESSED_AT
            , STATUS
        )
		VALUES(
			  SEQ_T_FRUIT_TARGET.NEXTVAL
			, #{item.fruitName, jdbcType=VARCHAR}
			, #{item.fruitQty, jdbcType=INTEGER}
			, SYSDATE
            , #{item.status, jdbcType=VARCHAR}
        )
